/// Comparison flavors. `Gt` / `Ge` are expressed by swapping operands of `Lt` / `Le`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum CmpKind {
    Eq,
    Ne,
    LtS,
    LeS,
    LtU,
    LeU,
    EqF32,
    NeF32,
    LtF32,
    LeF32,
    EqF64,
    NeF64,
    LtF64,
    LeF64,
    EqStr,
    NeStr,
    LtStr,
    LeStr,
}

/// Comparisons that have a fused compare-and-jump-if-false form.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum FusedKind {
    Eq,
    Ne,
    LtS,
    LeS,
    LtU,
    LeU,
    EqF64,
    NeF64,
    LtF64,
    LeF64,
}

impl CmpKind {
    /// The fused form of this comparison, if there is one.
    pub fn fused(self) -> Option<FusedKind> {
        Some(match self {
            CmpKind::Eq => FusedKind::Eq,
            CmpKind::Ne => FusedKind::Ne,
            CmpKind::LtS => FusedKind::LtS,
            CmpKind::LeS => FusedKind::LeS,
            CmpKind::LtU => FusedKind::LtU,
            CmpKind::LeU => FusedKind::LeU,
            CmpKind::EqF64 => FusedKind::EqF64,
            CmpKind::NeF64 => FusedKind::NeF64,
            CmpKind::LtF64 => FusedKind::LtF64,
            CmpKind::LeF64 => FusedKind::LeF64,
            _ => return None,
        })
    }
}

impl FusedKind {
    pub fn cmp(self) -> CmpKind {
        match self {
            FusedKind::Eq => CmpKind::Eq,
            FusedKind::Ne => CmpKind::Ne,
            FusedKind::LtS => CmpKind::LtS,
            FusedKind::LeS => CmpKind::LeS,
            FusedKind::LtU => CmpKind::LtU,
            FusedKind::LeU => CmpKind::LeU,
            FusedKind::EqF64 => CmpKind::EqF64,
            FusedKind::NeF64 => CmpKind::NeF64,
            FusedKind::LtF64 => CmpKind::LtF64,
            FusedKind::LeF64 => CmpKind::LeF64,
        }
    }
}
